import json
from pathlib import Path
B=Path(__file__).resolve().parent
R=[json.loads(s) for s in (B/'input.jsonl').read_text(encoding='utf-8').splitlines()]
P={}
def put(n,t,why):
    P[str(n)]={'decision':'change','target':t,'reason':why}
def replace(n,old,new,why):
    assert old in R[n]['target'], n
    put(n,R[n]['target'].replace(old,new),why)
